<script setup>
import { computed, ref } from 'vue'
import PageHeader from '@/components/ui/PageHeader.vue'
import { useActionFeedback } from '@/composables/useActionFeedback'
const { notify } = useActionFeedback()
const testCases = ref([{id:1,name:'Login functionality',type:'functional',status:'passed',priority:'high',lastRun:'2024-12-03'},{id:2,name:'Form validation',type:'functional',status:'passed',priority:'medium',lastRun:'2024-12-03'},{id:3,name:'API response times',type:'performance',status:'failed',priority:'high',lastRun:'2024-12-02'},{id:4,name:'Mobile responsiveness',type:'ui',status:'pending',priority:'medium',lastRun:'-'}])
const modal=ref(null), selected=ref(null), running=ref(false), draft=ref({name:'',type:'functional',priority:'medium',status:'pending'})
const stats=computed(()=>({total:testCases.value.length,passed:testCases.value.filter(t=>t.status==='passed').length,failed:testCases.value.filter(t=>t.status==='failed').length,pending:testCases.value.filter(t=>t.status==='pending').length}))
const openNew=()=>{selected.value=null;draft.value={name:'',type:'functional',priority:'medium',status:'pending'};modal.value='edit'}
const edit=t=>{selected.value=t;draft.value={...t};modal.value='edit'}
const save=()=>{if(!draft.value.name.trim())return;if(selected.value)Object.assign(selected.value,draft.value);else testCases.value.unshift({...draft.value,id:Date.now(),lastRun:'-'});modal.value=null;notify(selected.value?'Test case updated.':'Test case created.')}
const run=t=>{t.status='passed';t.lastRun=new Date().toISOString().slice(0,10);notify(`${t.name} passed.`)}
const runAll=()=>{running.value=true;setTimeout(()=>{testCases.value.forEach(t=>{t.status='passed';t.lastRun=new Date().toISOString().slice(0,10)});running.value=false;notify(`Completed ${testCases.value.length} test cases.`)},650)}
const remove=t=>{testCases.value=testCases.value.filter(x=>x.id!==t.id);modal.value=null;notify('Test case deleted.')}
</script>
<template><div><PageHeader title="QA & Testing" subtitle="Manage test cases and track quality metrics"><template #actions><button class="ti-btn ti-btn-light" data-feedback-handled="true" :disabled="running" @click="runAll"><i class="ri-loader-4-line me-1" :class="{ 'animate-spin': running }"></i>{{running?'Running tests...':'Run All Tests'}}</button><button class="ti-btn ti-btn-primary" data-feedback-handled="true" @click="openNew"><i class="ri-add-line me-1"></i> New Test Case</button></template></PageHeader><div class="grid grid-cols-12 gap-6"><div v-for="item in [['Total Tests',stats.total,'primary'],['Passed',stats.passed,'success'],['Failed',stats.failed,'danger'],['Pending',stats.pending,'warning']]" :key="item[0]" class="col-span-12 md:col-span-6 xl:col-span-3"><div class="box"><div class="box-body text-center"><h4 class="text-2xl font-bold" :class="`text-${item[2]}`">{{item[1]}}</h4><p class="text-textmuted">{{item[0]}}</p></div></div></div><div class="col-span-12"><div class="box"><div class="box-header"><h5 class="box-title">Test Cases</h5></div><div class="box-body p-0"><table class="table table-hover whitespace-nowrap"><thead><tr><th>Test Name</th><th>Type</th><th>Priority</th><th>Status</th><th>Last Run</th><th>Actions</th></tr></thead><tbody><tr v-for="test in testCases" :key="test.id"><td class="font-medium">{{test.name}}</td><td>{{test.type}}</td><td>{{test.priority}}</td><td><span class="badge" :class="test.status==='passed'?'bg-success/10 text-success':test.status==='failed'?'bg-danger/10 text-danger':'bg-warning/10 text-warning'">{{test.status}}</span></td><td>{{test.lastRun}}</td><td><div class="flex gap-1"><button class="ti-btn ti-btn-soft-primary ti-btn-icon ti-btn-sm" data-feedback-handled="true" aria-label="Run test" @click="run(test)"><i class="ri-play-line"></i></button><button class="ti-btn ti-btn-soft-info ti-btn-icon ti-btn-sm" data-feedback-handled="true" aria-label="Edit test" @click="edit(test)"><i class="ri-edit-line"></i></button><button class="ti-btn ti-btn-soft-danger ti-btn-icon ti-btn-sm" data-feedback-handled="true" aria-label="Delete test" @click="selected=test;modal='delete'"><i class="ri-delete-bin-line"></i></button></div></td></tr></tbody></table></div></div></div></div><div v-if="modal" class="fixed inset-0 z-[80] flex items-center justify-center bg-black/40" @click.self="modal=null"><div class="bg-white dark:bg-bgdark rounded-xl shadow-xl w-full max-w-md mx-4"><div class="px-6 py-4 border-b flex justify-between"><h3 class="font-semibold">{{modal==='edit'?(selected?'Edit Test Case':'New Test Case'):'Delete Test Case'}}</h3><button class="ti-btn ti-btn-sm ti-btn-light" @click="modal=null">Close</button></div><div v-if="modal==='edit'" class="p-6"><label class="ti-form-label">Test name</label><input v-model="draft.name" class="ti-form-control mb-3"><label class="ti-form-label">Type</label><input v-model="draft.type" class="ti-form-control mb-3"><label class="ti-form-label">Priority</label><select v-model="draft.priority" class="ti-form-select"><option>high</option><option>medium</option><option>low</option></select></div><div v-else class="p-6">Delete <b>{{selected.name}}</b>?</div><div class="px-6 py-4 border-t flex justify-end gap-2"><button class="ti-btn ti-btn-light" @click="modal=null">Cancel</button><button v-if="modal==='edit'" class="ti-btn ti-btn-primary" @click="save">Save</button><button v-else class="ti-btn ti-btn-danger" @click="remove(selected)">Delete</button></div></div></div></div></template>
